function sbReady(){ return window.MvpBackend.client; }
async function renderWTest(){
const __mvpEpoch=SessionGuard.capture();

 if(!AppSession.canOpen('wtest'))return;
 if(_wprofile.role==='student')return AppSession.context()?.mode==='server'&&AppSession.context()?.operations!=='legacy-compatible-v1'?MvpOperationalViews.studentTests():renderWStudent();
 return renderWTeacher();
}
async function renderWAdmin(){
const __mvpEpoch=SessionGuard.capture();

 if(!AppSession.canOpen('admin'))return;
 return renderWDirector();
}
// ===== 로그인 화면 =====
function renderWLogin(){
  const cont = document.getElementById('wtest-content');
  cont.innerHTML = `
  <div class="stg-card" style="max-width:380px;margin:20px auto;">
    <div class="stg-hdr"><div class="stg-icon">🔐</div><div class="stg-title">로그인</div></div>
    <div style="font-size:11px;color:var(--t3);margin-bottom:14px;">선생님이 발급한 이메일·비밀번호로 로그인하세요.</div>
    <div style="margin-bottom:10px;">
      <div class="form-lbl" style="margin-bottom:5px;">이메일</div>
      <input id="w-email" class="target-select" style="width:100%;" type="email" placeholder="student@example.com" autocomplete="username">
    </div>
    <div style="margin-bottom:14px;">
      <div class="form-lbl" style="margin-bottom:5px;">비밀번호</div>
      <input id="w-pw" class="target-select" style="width:100%;" type="password" placeholder="비밀번호" autocomplete="current-password">
    </div>
    <button onclick="wLogin()" style="width:100%;padding:11px;background:var(--accent);color:white;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;font-family:'Noto Sans KR',sans-serif;">로그인</button>
    <div id="w-login-msg" style="font-size:11px;color:var(--red);margin-top:10px;text-align:center;min-height:14px;"></div>
  </div>`;
  // 엔터키 로그인
  setTimeout(()=>{
    const pw=document.getElementById('w-pw');
    if(pw) pw.addEventListener('keydown',e=>{if(e.key==='Enter')wLogin();});
  },50);
}

async function wLogin(){
const __mvpEpoch=SessionGuard.capture();

  const sb=sbReady(); if(!sb)return;
  const email=document.getElementById('w-email').value.trim();
  const pw=document.getElementById('w-pw').value;
  const msg=document.getElementById('w-login-msg');
  msg.textContent='로그인 중...'; msg.style.color='var(--t3)';
  const { error } = await SessionGuard.wait((sb.auth.signInWithPassword({email, password:pw})),__mvpEpoch);
  if(error){ msg.style.color='var(--red)'; msg.textContent='로그인 실패: 이메일/비밀번호를 확인하세요.'; return; }
  renderWTest();
}

// ===== 학생 최초 이름·반 설정 =====
async function renderWSetup(){
const __mvpEpoch=SessionGuard.capture();

  const cont=document.getElementById('wtest-content');
  const sb=sbReady();
  const { data:classes } = await SessionGuard.wait((sb.from('classes').select('id,name').order('id')),__mvpEpoch);
  const opts=(classes||[]).map(c=>`<option value="${c.id}">${Ui.escape(c.name)}</option>`).join('');
  cont.innerHTML = `
  <div class="stg-card" style="max-width:400px;margin:20px auto;">
    <div class="stg-hdr"><div class="stg-icon">🙋</div><div class="stg-title">처음 오셨네요!</div></div>
    <div style="font-size:12px;color:var(--t2);line-height:1.7;margin-bottom:16px;">시험 결과와 명예의 전당에 사용할 <strong>이름</strong>과 <strong>반</strong>을 설정하세요.<br><span style="color:var(--red);font-size:11px;">⚠️ 한 번 설정하면 본인은 수정할 수 없고, 선생님만 변경할 수 있습니다. 정확히 입력하세요.</span></div>
    <div style="margin-bottom:12px;">
      <div class="form-lbl" style="margin-bottom:5px;">이름 (실명)</div>
      <input id="setup-name" class="target-select" style="width:100%;" placeholder="예: 홍길동">
    </div>
    <div style="margin-bottom:16px;">
      <div class="form-lbl" style="margin-bottom:5px;">반</div>
      <select id="setup-class" class="target-select" style="width:100%;">${opts||'<option value="">반 없음</option>'}</select>
    </div>
    <button onclick="wSaveSetup()" style="width:100%;padding:12px;background:var(--accent);color:white;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;font-family:'Noto Sans KR',sans-serif;">설정 완료</button>
    <div style="text-align:center;margin-top:10px;"><span onclick="wLogout()" style="font-size:11px;color:var(--t3);cursor:pointer;text-decoration:underline;">다른 계정으로 로그인</span></div>
  </div>`;
}
async function wSaveSetup(){
const __mvpEpoch=SessionGuard.capture();

  const sb=sbReady();
  const name=document.getElementById('setup-name').value.trim();
  const cls=document.getElementById('setup-class').value;
  if(!name){ alert('이름을 입력하세요.'); return; }
  if(!confirm(`이름 "${Ui.escape(name)}"으로 설정할까요?\n설정 후에는 본인이 변경할 수 없습니다.`)) return;
  const { error } = await SessionGuard.wait((sb.rpc('set_my_profile', { p_name:name, p_class_id: cls?parseInt(cls):null })),__mvpEpoch);
  if(error){
    // 관리자가 이 화면이 열린 사이 이름을 지정했거나 구버전 RPC가 재호출을
    // 거절한 경우, 최신 프로필을 확인해 설정 화면에 갇히지 않도록 복구한다.
    if(String(error.message||'').includes('최초 설정이 이미 완료')){
      const { data:latest } = await SessionGuard.wait((sb.from('profiles').select('id,name,nickname,student_no,role,class_id,teacher_id,pw_changed').eq('id',_wuser.id).maybeSingle()),__mvpEpoch);
      if(latest && String(latest.name||'').trim()){
        _wprofile=latest;
        showToast('관리자가 설정한 학생 정보로 시작합니다.');
        renderWStudent();
        return;
      }
    }
    alert('설정 실패: '+error.message); return;
  }
  showToast('설정 완료!');
  renderWTest();
}

async function wEditNick(){
const __mvpEpoch=SessionGuard.capture();

  const cur=_wprofile.nickname||'';
  const nick=prompt('명예의 전당에 표시할 닉네임을 입력하세요 (실명이 아니어도 됩니다):', cur);
  if(nick===null) return;
  const sb=sbReady();
  const { error } = await SessionGuard.wait((sb.rpc('set_my_nickname', { p_nick: nick.trim() })),__mvpEpoch);
  if(error){ alert('변경 실패: '+error.message); return; }
  _wprofile.nickname = nick.trim();
  showToast('닉네임 변경됨');
  renderWStudent();
}

// 학생 본인 비밀번호 변경
async function wChangePw(){
 if(window.MvpBackend.preview){showToast('체험 계정에는 비밀번호 변경을 연결하지 않았습니다.');return;}
 const context=window.AppSession?.context();
 if(!context||!AppSession.can('own-profile'))return;
 const previous=document.getElementById('self-password-dialog');
 if(previous){previous.querySelector('input')?.focus();return;}
 const epoch=SessionGuard.capture(),owner=context.id,returnFocus=document.activeElement;
 const dialog=document.createElement('dialog');dialog.id='self-password-dialog';
 dialog.setAttribute('aria-labelledby','self-password-title');
 dialog.style.cssText='width:min(420px,calc(100vw - 32px));box-sizing:border-box;padding:24px;border:1px solid var(--border,#d8dee8);border-radius:16px;color:var(--t1,#172033);background:var(--surface,#fff)';
 dialog.innerHTML='<form id="self-password-form" style="display:grid;gap:14px"><h2 id="self-password-title" style="margin:0;font-size:20px">비밀번호 변경</h2><label style="display:grid;gap:6px">새 비밀번호 (6자 이상)<input id="self-password-new" type="password" autocomplete="new-password" minlength="6" maxlength="256" required style="font:inherit;padding:10px;min-width:0"></label><label style="display:grid;gap:6px">새 비밀번호 확인<input id="self-password-confirm" type="password" autocomplete="new-password" minlength="6" maxlength="256" required style="font:inherit;padding:10px;min-width:0"></label><p id="self-password-status" role="status" aria-live="polite" style="margin:0"></p><div style="display:flex;gap:8px;justify-content:flex-end"><button id="self-password-cancel" type="button" style="padding:10px 16px">취소</button><button id="self-password-save" type="submit" style="padding:10px 16px">변경 확인</button></div></form>';
 const form=dialog.querySelector('form'),first=dialog.querySelector('#self-password-new'),second=dialog.querySelector('#self-password-confirm'),message=dialog.querySelector('#self-password-status');
 let busy=false,closed=false;
 const same=()=>{const now=AppSession.context();return !closed&&dialog.isConnected&&now?.id===owner&&now.epoch===epoch&&AppSession.can('own-profile');};
 const wipe=()=>{first.value='';second.value='';};
 function finish(restore=true){if(closed)return;closed=true;wipe();window.removeEventListener('mvp-session-reset',reset);if(dialog.open)dialog.close();dialog.remove();if(restore&&AppSession.context()?.id===owner&&SessionGuard.capture()===epoch&&returnFocus?.isConnected)returnFocus.focus();}
 function reset(){finish(false);}
 function feedback(text){if(!same())return;message.textContent=text;message.setAttribute('role','alert');}
 function waiting(value){busy=value;form.querySelectorAll('input,button').forEach(node=>{node.disabled=value;});form.setAttribute('aria-busy',String(value));}
 dialog.querySelector('#self-password-cancel').addEventListener('click',()=>{if(!busy)finish();});
 dialog.addEventListener('cancel',event=>{event.preventDefault();if(!busy)finish();});
 dialog.addEventListener('close',()=>finish());
 window.addEventListener('mvp-session-reset',reset);
 form.addEventListener('submit',async event=>{
  event.preventDefault();if(busy||!same())return;
  if(first.value.length<6||first.value.length>256){feedback('비밀번호는 6자 이상 256자 이하로 입력해 주세요.');first.focus();return;}
  if(first.value!==second.value){feedback('두 비밀번호가 일치하지 않습니다.');second.focus();return;}
  waiting(true);message.textContent='비밀번호를 변경하고 있습니다.';message.setAttribute('role','status');
  let changed=false;
  try{
   const result=await sbReady().auth.updateUser({password:first.value});
   if(!same())return;
   if(result.error){wipe();feedback('비밀번호를 변경하지 못했습니다. 연결 상태를 확인한 뒤 다시 시도해 주세요.');return;}
   changed=true;wipe();
   const marker=await sbReady().from('profiles').update({pw_changed:true}).eq('id',owner);
   if(!same())return;
   if(marker.error){showToast('비밀번호는 변경됐지만 계정의 변경 표시를 갱신하지 못했습니다.');finish();return;}
   if(_wprofile&&_wuser?.id===owner)_wprofile.pw_changed=true;
   showToast('비밀번호가 변경되었습니다.');finish();
  }catch(_error){if(!same())return;wipe();if(changed){showToast('비밀번호는 변경됐지만 계정의 변경 표시를 갱신하지 못했습니다.');finish();}else feedback('비밀번호를 변경하지 못했습니다. 연결 상태를 확인한 뒤 다시 시도해 주세요.');}
  finally{if(same()){waiting(false);first.focus();}}
 });
 document.body.append(dialog);
 if(typeof dialog.showModal!=='function'){finish();showToast('이 브라우저에서 비밀번호 변경 창을 열 수 없습니다. 브라우저를 업데이트해 주세요.');return;}
 dialog.showModal();first.focus();
}

