async function wSaveTeacherName(){
const __mvpEpoch=SessionGuard.capture();

  const sb=sbReady();
  const name=document.getElementById('tsetup-name').value.trim();
  if(!name){ alert('이름을 입력하세요.'); return; }
  // 선생님은 본인 name 직접 수정 (RLS: student self update 정책이 본인 행 허용)
  const { error } = await SessionGuard.wait((sb.from('profiles').update({name}).eq('id', _wuser.id)),__mvpEpoch);
  if(error){ alert('저장 실패: '+error.message); return; }
  _wprofile.name=name;
  showToast('이름 저장됨');
  renderWTest();
}

async function wLogout(){
const __mvpEpoch=SessionGuard.capture();

  const sb=sbReady(); if(!sb)return;
  await SessionGuard.wait((sb.auth.signOut()),__mvpEpoch);
  _wuser=null; _wprofile=null;
  scores=readScoresLocal('');
  renderScore();renderTrend();renderUni();renderStrategy();
  vwClose(); vwCacheClear();
  document.querySelectorAll('.cat[data-cat="counsel"],.cat[data-cat="exam-counsel"]').forEach(el=>{
    el.style.display='none';
  });
  const staffOpen=document.querySelector('.cat[data-cat="counsel"].on,.cat[data-cat="exam-counsel"].on');
  // 계정관리 탭 숨기고, 보고 있었으면 테스트 탭으로
  const adminCat=document.querySelector('.cat[data-cat="admin"]');
  if(adminCat){
    adminCat.style.display='none';
    if(adminCat.classList.contains('on')){ showCat('wtest'); return; }
  }
  if(staffOpen){ showCat('wtest'); return; }
  renderWLogin();
}

// ===== 학생 화면 =====
async function renderWStudent(){
  const epoch=SessionGuard.capture(),cont=document.getElementById('wtest-content'),sb=sbReady(),owner=_wuser?.id;
  if(!cont||!sb||!owner||_wprofile?.role!=='student')return;
  const nick=_wprofile.nickname||'';
  cont.innerHTML=wHeader(_wprofile.name||'학생','학생')+
    '<section class="stg-card student-test-list"><div class="str-profile"><div><p>결과 · 명예의 전당 닉네임</p><strong>'+Ui.escape(nick||'미설정 (익명)')+'</strong></div><button type="button" onclick="wEditNick()">닉네임 '+(nick?'변경':'설정')+'</button><button type="button" onclick="wChangePw()">비밀번호 변경</button></div></section>';
  const region=document.createElement('section');region.className='stg-card student-test-list';region.innerHTML='<p role="status">테스트 목록을 불러오는 중입니다.</p>';cont.append(region);
  try{
    const [assigned,submitted]=await SessionGuard.wait(Promise.all([
      sb.from('test_assignments').select('test_id').eq('user_id',owner),
      sb.from('submissions').select('test_id,score,correct_count').eq('user_id',owner)
    ]),epoch);
    if(!region.isConnected)return;
    if(assigned.error||submitted.error||!Array.isArray(assigned.data)||!Array.isArray(submitted.data))throw Error('unavailable');
    const ids=[...new Set([...assigned.data,...submitted.data].map(r=>r.test_id))].filter(id=>Number.isSafeInteger(Number(id))&&Number(id)>0);
    if(!ids.length){region.innerHTML='<h2>테스트 목록</h2><p>아직 배정된 테스트가 없습니다.</p>';return;}
    const result=await SessionGuard.wait(sb.from('tests').select('id,title,total,exam_date,closed').in('id',ids).order('exam_date',{ascending:false}),epoch);
    if(!region.isConnected)return;
    if(result.error||!Array.isArray(result.data))throw Error('unavailable');
    const submissions=new Map(submitted.data.map(row=>[row.test_id,row]));
    region.innerHTML='<h2>테스트 목록</h2><p class="str-list-note">응시한 테스트에서 등수와 문항별 결과를 확인하세요.</p>'+result.data.map(t=>{
      if(!Number.isSafeInteger(Number(t.id))||Number(t.id)<1)return '';
      const mine=submissions.get(t.id),score=mine?.score!=null&&Number.isFinite(Number(mine.score))?Number(mine.score)+'점':'채점 확인 중';
      const action=mine?'wResultView':'wOpenTest',disabled=!mine&&t.closed;
      return '<article class="str-test-row"><div><h3>'+Ui.escape(t.title)+'</h3><p>'+Ui.escape(t.exam_date||'')+' · '+Number(t.total)+'문항 · '+(t.closed?'마감':'진행 중')+'</p></div><div class="str-test-action"><span>'+(mine?'제출 완료 · '+score:disabled?'마감됨':'미응시')+'</span><button type="button" '+(disabled?'disabled':'onclick="'+action+'('+Number(t.id)+','+Ui.argument(t.title)+','+Number(t.total)+')"')+'>'+(mine?'등수 · 문항별 결과':disabled?'마감':'응시하기')+'</button></div></article>';
    }).join('');
  }catch(error){
    if(error?.name==='StaleSession'||!region.isConnected)return;
    region.innerHTML='<p role="alert">테스트 목록을 불러오지 못했습니다. 다시 확인해 주세요.</p><button type="button" onclick="renderWStudent()">다시 불러오기</button>';
  }
}

// 테스트 응시 화면 (미응시 학생만)
async function wOpenTest(testId, title, total){
const __mvpEpoch=SessionGuard.capture();

  const cont=document.getElementById('wtest-content');
  const sb=sbReady();
  // 이미 제출했으면 결과 화면으로
  const { data:already } = await SessionGuard.wait((sb.from('submissions').select('test_id').eq('test_id',testId).eq('user_id',_wuser.id).maybeSingle()),__mvpEpoch);
  if(already){ wResultView(testId, title, total); return; }
  const { data:test } = await SessionGuard.wait((sb.from('tests').select('types,closed').eq('id',testId).single()),__mvpEpoch);
  if(test && test.closed){ alert('이미 마감된 테스트입니다.'); renderWStudent(); return; }
  const types = (test && test.types) ? test.types : new Array(total).fill('mc');
  window._wTypes = types;

  let rows='';
  let hasSA=false;
  for(let i=0;i<total;i++){
    const type=types[i]||'mc';
    if(type==='mc'){
      let opts='';
      for(let n=1;n<=5;n++){
        opts += `<button class="omr-bubble" data-q="${i}" data-n="${n}" onclick="wPick(${i},${n})">${n}</button>`;
      }
      rows += `<div class="omr-row"><div class="omr-qn">${i+1}</div><div class="omr-opts">${opts}</div></div>`;
    } else {
      hasSA=true;
      rows += `<div class="omr-row" style="align-items:center;"><div class="omr-qn">${i+1}</div>
        <span style="font-size:9px;color:var(--a3);font-weight:700;flex-shrink:0;margin-right:4px;">주관식</span>
        <input class="w-sa-inp" data-saq="${i}" oninput="wTypeStudent(${i},this.value)" placeholder="답 입력" style="flex:1;padding:6px 9px;border:1px solid var(--border);border-radius:6px;font-size:12px;font-family:'Noto Sans KR',sans-serif;"></div>`;
    }
  }

  cont.innerHTML = wHeader(_wprofile.name||'학생','학생') + `
  <div class="stg-card">
    <div class="stg-hdr"><div class="stg-icon">✏️</div><div class="stg-title">${Ui.escape(title)}</div><div class="stg-sub">${total}문항</div></div>
    <div style="background:linear-gradient(135deg,#eef2ff,#e0e7ff);border:1px solid var(--accent-mid);border-radius:10px;padding:12px;margin-bottom:12px;">
      <div style="font-size:12px;font-weight:700;color:var(--accent);margin-bottom:6px;">📷 OMR 카드 자동 입력</div>
      <div style="font-size:10px;color:var(--t2);line-height:1.6;margin-bottom:8px;">OMR 카드를 평평하게 펴고 밝은 곳에서 <strong>표 전체가 보이게</strong> 정면으로 촬영하면 답이 자동으로 채워져요.<br>✅ 정확한 인식을 위해 <strong>동그라미·숫자 칸을 진하게 꽉 채워</strong> 칠하세요. (연하거나 빗금만 친 마킹은 인식이 어려울 수 있어요.)<br>인식 후 꼭 직접 확인하세요.</div>
      <input id="omr-file" type="file" accept="image/*" capture="environment" style="display:none;" onchange="wOmrScan(this)">
      <button onclick="document.getElementById('omr-file').click()" style="width:100%;padding:11px;background:var(--accent);color:white;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;font-family:'Noto Sans KR',sans-serif;">📷 OMR 촬영 / 사진 선택</button>
      <div id="omr-scan-status" style="font-size:11px;margin-top:8px;text-align:center;"></div>
    </div>
    <div style="font-size:11px;color:var(--t3);margin-bottom:12px;">객관식은 번호 선택, ${hasSA?'주관식은 답을 직접 입력하세요.':'답을 선택하세요.'}<br>⚠️ 제출 후에는 답을 수정할 수 없습니다.</div>
    <div class="omr-sheet">${rows}</div>
    <button id="w-submit-btn" onclick="wSubmit(${testId},${total},${Ui.argument(title)})" style="width:100%;margin-top:14px;padding:12px;background:var(--accent);color:white;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;font-family:'Noto Sans KR',sans-serif;">제출하고 채점하기</button>
    <button onclick="renderWStudent()" style="width:100%;margin-top:8px;padding:10px;background:var(--surface);color:var(--t2);border:1px solid var(--border);border-radius:8px;font-size:12px;cursor:pointer;font-family:'Noto Sans KR',sans-serif;">← 목록으로</button>
  </div>`;
  window._wAnswers = new Array(total).fill('');
  window._wTestId = testId;
  window._wTotal = total;
}

